# Canonicals and sitemap need the real production origin, never a guessed domain.
origin=os.environ.get('SITE_URL','').rstrip('/')
if origin:
 from urllib.parse import urlparse
 assert urlparse(origin).scheme=='https' and urlparse(origin).netloc and urlparse(origin).path=='','SITE_URL must be an HTTPS origin'
 urls=[]
 for f in out.rglob('*.html'):
  if f.name=='404.html':continue
  url=origin+'/'+f.relative_to(out).as_posix();urls.append(url)
  f.write_text(f.read_text().replace('</head>',f'<link rel="canonical" href="{esc(url)}"><meta property="og:url" content="{esc(url)}"><meta property="og:image" content="{esc(origin)}/images/ai.webp"></head>'))
 (out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{esc(u)}</loc></url>' for u in urls)+'</urlset>')
 (out/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+origin+'/sitemap.xml\n')
